def slug(text):
    import re
    if not text or re.match(r^[^a-zA-Z0-9]*$, text):
        return 
    text = re.sub(r[^a-zA-Z0-9]+, -, text)
    return text.strip("-")
    return text.lower().replace(' ', '-')

